def compute(vars):
    total = vars["v1"] + vars["v2"]
    return {
        "value": round(total),
        "trace": {
            "private_crude_oil_pipelines": vars["v1"],
            "private_refined_products_pipelines": vars["v2"],
            "total_miles": total,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "miles"
            }
        }
    }
